/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"bassstation-level-4","number":4,"title":"Computer Integration, USB MIDI & Novation Components","skillBand":"Textbook","duration":"From the course textbook","summary":"- Configure class-compliant USB MIDI communication on both Windows and macOS operating systems. - Differentiate between operating system class-compliant drivers and optional Novation USB drivers on Windows.","modules":[{"id":"bassstation-m-4-1","code":"4","title":"Computer Integration, USB MIDI & Novation Components","blurb":"- Configure class-compliant USB MIDI communication on both Windows and macOS operating systems. - Differentiate between operating system class-compliant drivers and optional Novation USB drivers on Windows.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"bassstation-l-o-4","title":"Section overview","blocks":[{"type":"step","title":"Section 4.1 — USB MIDI on Windows and macOS","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Configure class-compliant USB MIDI communication on both Windows and macOS operating systems.","Differentiate between operating system class-compliant drivers and optional Novation USB drivers on Windows.","Master the technical operation and power-cycle behavior of Local Control (<code>On</code> vs. <code>Off</code>).","Configure the Global MIDI Channel via On-Key programming and verify non-volatile retention.","Enforce the fundamental hardware rule regarding MIDI routing isolation (the \"Not a MIDI Interface\" rule)."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-4-1-1","title":"4.1.1: Class-Compliant USB Architecture","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Novation Bass Station II implements the official USB MIDI class-compliant protocol (USB 1.1 / 2.0 interface specification)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[Host Computer (Windows / macOS)]\n  │\n  ├── Standard USB 2.0 Type-A/C Port\n  │     │ (USB A-to-B Cable)\n  │     ▼\n  └── [Bass Station II USB Type-B Port]\n        ├── Microprocessor Core (Endpoints: MIDI In / MIDI Out)\n        └── 5 V DC Bus Power Pin (Optional Operating Power)</pre>"},{"type":"list","items":["<strong>Driverless Plug-and-Play</strong>:","The device requires no proprietary kernel drivers for standard MIDI communication.","Upon connection, the host operating system’s native CoreAudio/CoreMIDI (macOS) or generic USB Audio/MIDI driver stack (Windows) recognizes the instrument as a standard MIDI device.","<strong>Data Streaming Capabilities</strong>:","Transmits real-time note-on/note-off messages with 7-bit velocity (0–127).","Transmits Channel Aftertouch (0–127).","Transmits continuous 7-bit MIDI Control Change (CC) messages and 14-bit Non-Registered Parameter Numbers (NRPN) for real-time front-panel knob and fader manipulation.","Transmits and receives System Exclusive (SysEx) data blocks for two-way librarian and firmware transfers."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Connect the supplied USB A-to-B cable between the synthesizer and a host computer.","Power on the synthesizer via <code>ext DC</code> or <code>USB</code>.","Open a MIDI monitoring application (e.g., MIDI Monitor on macOS, MIDI-OX on Windows, or Ableton Live MIDI Preferences); verify that \"Bass Station II\" appears immediately in the input/output port lists."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-1-2","title":"4.1.2: Windows Operating System Configuration & Device Manager","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Device Enumeration</strong>:","On Windows 10 and 11, the Bass Station II enumerates under <strong>Device Manager</strong> -&gt; <strong>Sound, video and game controllers</strong> as <code>Bass Station II</code> (or generic <code>USB Audio Device</code> under generic drivers).","<strong>Novation USB Driver</strong>:","While class-compliant MIDI operates under generic Windows drivers, Novation provides an official <strong>Novation USB Driver</strong> (available from <code>downloads.novationmusic.com</code>).","<em>Why Install</em>: The dedicated driver improves multi-client MIDI performance (allowing multiple DAW applications or browser-based Web MIDI tools to access the synth simultaneously) and ensures stable high-speed SysEx communication with Novation Components.","<strong>USB Hub Architecture &amp; Error Code 10</strong>:","Always connect the synthesizer directly to a dedicated motherboard USB root hub port.","Avoid unpowered external USB hubs, passive monitor hubs, or unshielded extension cables, which can cause Windows device enumeration failures (e.g., Device Manager <code>Code 10: Device Cannot Start</code>)."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">              WINDOWS TROUBLESHOOTING DIAGNOSTIC TREE\n     [Synthesizer Not Seen in Windows DAW / Components]\n                       │\n     ├── Direct Motherboard USB Port Used? (No ──► Connect Directly)\n     ├── Device Manager: Error Code 10 / Yellow Bang?\n     │     └── Yes ──► Install Official Novation USB Driver from downloads.novationmusic.com\n     └── Chrome/Edge Web MIDI Permission Granted? (No ──► Allow MIDI Access in Browser)</pre>"}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["On Windows, press <code>Win + X</code> and select <strong>Device Manager</strong>.","Expand <strong>Sound, video and game controllers</strong>.","Verify that <code>Bass Station II</code> appears without a yellow warning icon (\"bang\")."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-1-3","title":"4.1.3: macOS Operating System Configuration & Audio MIDI Setup","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>CoreMIDI Architecture</strong>:","On macOS, the Bass Station II communicates directly with Apple's native CoreMIDI framework without third-party kernel extensions.","<strong>Audio MIDI Setup Utility</strong>:","Launching <code>/Applications/Utilities/Audio MIDI Setup.app</code> and pressing <code>Cmd + 2</code> opens the <strong>MIDI Studio</strong> window.","The Bass Station II appears as an active icon named <code>Bass Station II</code> with 1 In and 1 Out port.","If the icon appears dimmed/greyed out, macOS indicates the physical USB connection is severed or the unit is powered off."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["On macOS, open <strong>Audio MIDI Setup</strong>.","Switch to the <strong>MIDI Studio</strong> window.","Power the Bass Station II off, then on; observe the <code>Bass Station II</code> icon toggle between inactive (greyed) and active (highlighted)."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-1-4","title":"4.1.4: Local Control Architecture","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Local Control determines whether the physical keyboard and front-panel controls directly trigger the internal analogue sound engine or communicate solely via MIDI."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                    LOCAL CONTROL SIGNAL FLOW\n  ┌─────────────────────────────────────────────────────────────┐\n  │ [Physical Keybed &amp; Knobs]                                   │\n  │        │                                                    │\n  │        ├─────── (Local Control = ON) ──────────► [Sound]    │\n  │        │                                         [Engine]   │\n  │        ▼ (Transmits MIDI)                           ▲       │\n  │   [MIDI OUT / USB]                                  │       │\n  │        │                                            │       │\n  │        ▼                                            │       │\n  │   [DAW / MIDI Track] ──► (Echoes MIDI Back) ────────┘       │\n  │                          (Local Control = OFF)              │\n  └─────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong><code>Local On</code> (Default State)</strong>:","The physical keybed and pitch/mod wheels are internally hardwired to the synthesis engine.","Playing keys generates sound immediately, while simultaneously transmitting MIDI notes over USB and DIN.","<strong><code>Local Off</code> (DAW Studio Integration Mode)</strong>:","The internal connection between the keyboard/panel and the sound engine is severed.","Playing keys transmits MIDI out to the DAW, but produces <strong>zero sound directly from the synthesizer</strong>.","Sound is produced only when the DAW echoes (monitors) the MIDI track back into the Bass Station II input.","<em>Why Use Local Off</em>: Prevents \"MIDI echo doubling\" (where notes trigger twice in rapid succession, cutting off polyphony/envelopes) when recording into a DAW with MIDI track monitoring active.","<strong>The Power-Cycle Volatility Rule</strong>:","<strong>Local Control is NOT saved across power cycles</strong>.","Every time the Bass Station II is powered off and on, <strong>Local Control automatically reverts to <code>On</code></strong>."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Press <strong>Function / Exit</strong>, then press the <strong>Local</strong> key (the upper <code>A</code> key).","The display shows <code>On</code>. Press <strong>Patch/Value ▼</strong> to switch the display to <code>OFF</code>.","Press <strong>Function / Exit</strong> to return to play mode.","Strike several keys on the keyboard. Confirm that <strong>no sound is generated</strong> even though Volume is turned up.","Power cycle the synthesizer (switch to <code>OFF</code>, then back to <code>ext DC</code>).","Strike a key; confirm that sound generation has automatically restored because Local Control reset to <code>On</code>."],"ordered":true}]},{"type":"step","title":"3. Self-Assessment Checkpoint","blocks":[{"type":"list","items":["[ ] What is the purpose of setting Local Control to Off during DAW recording?","[ ] What state does Local Control assume after the synthesizer is power cycled?"],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-4-1-5","title":"4.1.5: Global MIDI Channel Configuration","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Global MIDI Channel Range</strong>:","The Bass Station II transmits and receives all note, controller, and program change data on a single global MIDI channel from <strong>1 to 16</strong>.","<strong>Configuration Sequence</strong>:","Press <strong>Function / Exit</strong>.","Press the <strong>Global MIDI Channel</strong> key (the upper <code>G#</code> key).","The display indicates the current active channel (default is <code>1</code>).","Use the <strong>Patch/Value ▲ and ▼</strong> buttons to select any channel from <code>1</code> to <code>16</code>.","Press <strong>Function / Exit</strong> to exit.","<strong>Non-Volatile Retention</strong>:","Unlike Local Control, the selected <strong>MIDI Channel IS saved across power cycles</strong>. Once set to Channel 3, the unit boots to Channel 3 indefinitely until manually changed."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Enter Function mode, select <strong>MIDI Channel</strong> (upper <code>G#</code>), and change the value to <code>5</code>.","Exit Function mode.","Power cycle the unit.","Enter Function mode, press upper <code>G#</code>, and verify that the display confirms channel <code>5</code> was retained in non-volatile memory. Reset back to Channel <code>1</code>."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-1-6","title":"4.1.6: The \"Not a MIDI Interface\" Routing Rule","blocks":[{"type":"step","title":"4.1.6: The \"Not a MIDI Interface\" Routing Rule","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"A common point of confusion in hybrid hardware studios is assuming the Bass Station II acts as a 2-way USB-to-DIN MIDI converter."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">               HARDWARE ROUTING ISOLATION MAP\n   [Host Computer] ──► (USB MIDI) ──► [Internal Synth Engine] (CONSUMED)\n                                                │\n                                      (NO DATA ROUTING TO DIN!)\n                                                │\n                                                ▼\n                                    [5-Pin DIN MIDI OUT] (DEAD)</pre>"},{"type":"list","items":["<strong>Rule</strong>: Data sent from a computer over USB to the Bass Station II is consumed strictly by the internal synthesis microprocessor.","The Bass Station II <strong>does not re-transmit, bridge, or echo incoming USB MIDI data out through its rear 5-Pin DIN MIDI OUT jack</strong>.","External hardware synths connected to the 5-Pin DIN OUT will not receive MIDI generated by your DAW over USB."],"ordered":false}]},{"type":"step","title":"Section 4.2 — Registration, Novation Components, and Firmware","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Execute product registration to unlock bundled software licenses and standalone utility access.","Deploy Novation Components via Web MIDI (Chrome, Edge, Opera) and Standalone desktop installers (Windows/macOS).","Interpret the three visual connection status states (Red, Yellow, Green) in Novation Components.","Perform patch librarian operations, backup user banks, and execute firmware updates safely."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-4-2-1","title":"4.2.1: Product Registration and Account Ecosystem","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Registration Portal</strong>:","Registration is completed at <code>novationmusic.com/register/product</code>.","Requires entering the serial number located on the underside barcode label and the bundle access code printed on the Getting Started insert.","<strong>Account Assets</strong>:","Unlocks downloadable software bundles (such as DAW starter software, virtual instrument plugins, and third-party sample content).","Provides direct download links for the <strong>Novation Components Standalone Installer</strong> for offline patch management."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-2-2","title":"4.2.2: Novation Components: Web MIDI vs. Standalone Application","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Novation Components is the official patch librarian, overlay editor, micro-tuning manager, and firmware delivery platform for the Bass Station II."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                       NOVATION COMPONENTS PLATFORMS                        │\n├───────────────────────────────────┬────────────────────────────────────────┤\n│ Web MIDI Browser Platform         │ Standalone Desktop Application         │\n├───────────────────────────────────┼────────────────────────────────────────┤\n│ • URL: components.novationmusic.com│ • Native Windows (.exe) / macOS (.dmg) │\n│ • Supported: Google Chrome, Edge, │ • No internet connection required once │\n│   Opera (Blink engine Web MIDI)   │   installed                            │\n│ • NOT Supported: Safari, Firefox  │ • Accessible via Novation Account or   │\n│   (Lack native Web MIDI API)      │   Components \"Install App\" user menu   │\n└───────────────────────────────────┴────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Web MIDI Requirements</strong>:","Access via <code>components.novationmusic.com</code>.","Requires a browser with native Web MIDI API support (Google Chrome, Microsoft Edge, Opera).","Safari and Mozilla Firefox do not support Web MIDI SysEx communication and cannot communicate with the hardware.","<strong>Standalone Desktop Application</strong>:","Installable directly on Windows and macOS.","Recommended for studio workstations without persistent internet connections or in touring environments."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-2-3","title":"4.2.3: Connection Status Indicators (Red / Yellow / Green)","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The top-right corner of the Novation Components interface displays a color-coded hardware connection status badge:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                    COMPONENTS CONNECTION STATUS BADGES                      │\n├─────────┬──────────────────┬────────────────────────────────────────────────┤\n│ Badge   │ Hardware State   │ Diagnostic &amp; Corrective Action                 │\n├─────────┼──────────────────┼────────────────────────────────────────────────┤\n│ 🔴 RED  │ Disconnected     │ Cable detached; power switch off; USB fault.   │\n│ 🟡 YELLOW│ Incorrect State  │ Unit in Bootloader mode; MIDI port in use by   │\n│         │ or Locked Port   │ another app. Press 'Play' or close DAW.        │\n│ 🟢 GREEN│ Connected &amp; Ready│ Fully enumerated; bidirectional SysEx active.  │\n└─────────┴──────────────────┴────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Red Indicator (Not Connected)</strong>:","Synthesizer is powered off, USB cable is disconnected, or operating system driver failed to enumerate.","<strong>Yellow Indicator (Attention / Bootloader State)</strong>:","Synthesizer is connected but in an abnormal operating state (e.g., stuck in Bootloader mode displaying <code>bLt</code> or <code>UPd</code>).","Alternatively, another DAW software (e.g., Ableton Live) has locked exclusive access to the MIDI ports on Windows. Close background MIDI applications.","<em>Bootloader Recovery</em>: If stuck in bootloader, press the <strong>On / Legato</strong> (Play) button to boot into standard operating mode, or run a firmware re-install.","<strong>Green Indicator (Connected)</strong>:","Full bidirectional communication established. Hardware is ready for real-time librarian and editing workflows."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Open Google Chrome and navigate to <code>components.novationmusic.com</code>.","Connect your Bass Station II via USB and power on the unit.","Observe the connection badge change from Red to <strong>Green</strong>."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-2-4","title":"4.2.4: Functional Architecture of Components","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Components manages five discrete digital functional domains on the Bass Station II:"},{"type":"list","items":["<strong>Patches (Librarian)</strong>: Back up, organize, audition, and load 128-patch banks or individual sounds.","<strong>AFX Mode Overlays</strong>: Build, edit, and organize 8 banks of 25-key patch overlays; provides real-time Live Edit and Autostep sampling helpers.","<strong>Tuning Tables</strong>: Create, edit, and upload custom micro-tonal scale tables (Tables 1 through 8).","<strong>Startup Message</strong>: Program custom text splash greetings scrolling across the 7-segment display on boot.","<strong>Firmware Updates</strong>: Delivers official firmware releases directly to the hardware flash memory."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-4-2-5","title":"4.2.5: Firmware Update Protocol","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Firmware updates introduce new synthesis features, micro-tuning capabilities, overlay handling, and stability fixes."},{"type":"list","items":["<strong>Rule of Version Honesty</strong>: Never rely on a frozen version number written in static notes. Firmware updates are dynamic; always query Novation Components for the current authoritative build for your serial number.","<strong>Update Execution Routine</strong>:","Ensure the synthesizer is connected directly to computer USB and powered via the <strong>supplied 9 V DC adapter</strong> to prevent power loss during EEPROM flashing.","In Components, navigate to <strong>Updates / Firmware</strong>.","Click <strong>Install Update</strong>. Do not disconnect USB or power off the unit while the display shows flashing programming progress.","Upon completion, the synthesizer automatically reboots into normal play mode."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-4-2-6","title":"4.2.6: Offline Bank Preparation and Cloud Sync","blocks":[{"type":"step","title":"4.2.6: Offline Bank Preparation and Cloud Sync","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"list","items":["<strong>Offline Management</strong>:","You can create, organize, and edit patch libraries and AFX overlay banks inside Components without the physical synthesizer attached.","<strong>Cloud &amp; Local Storage</strong>:","When logged in with a Novation account, custom banks sync to cloud storage.","Banks can also be exported locally as <code>.syx</code> (System Exclusive) files for archiving and studio distribution.","<strong>Transmission</strong>:","Once the physical hardware is reconnected (Green indicator), clicking <strong>Send to Bass Station II</strong> flashes the prepared bank into onboard memory."],"ordered":true}]},{"type":"step","title":"Assessment Gate C — Self-Assessment Checkpoint","blocks":[{"type":"prose","html":"Before advancing to Module 5, verify complete mastery of Gate C proficiencies:"},{"type":"list","items":["[ ] <strong>USB Enumeration</strong>: Verify that your Bass Station II enumerates cleanly as a MIDI device in both your OS settings and your primary DAW.","[ ] <strong>Components Connection</strong>: Connect to Novation Components (web or standalone) and achieve a <strong>Green</strong> connection status.","[ ] <strong>Local Control Protocol</strong>: Explain the operational difference between <code>Local On</code> and <code>Local Off</code>, demonstrate toggling the parameter, and verify why it resets to <code>On</code> at boot.","[ ] <strong>MIDI Channel Retention</strong>: Set the Global MIDI Channel to <code>3</code>, power cycle the unit, and verify that the setting was retained.","[ ] <strong>Diagnostic Resolution</strong>: Explain the exact meaning of a Yellow connection status in Components and the corrective steps required."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
